"""Persist completed native visual observations; hashes bind statements to saved PNGs."""
import json,hashlib,time
from pathlib import Path
p=Path(__file__).resolve().parent
notes={'calibration-original':'Face remains coherent. Relative to baseline, white neck patch narrows and dark rough texture expands into its left margin. Remaining white patch still resembles lit skin, with original folded shirt visible; no clean collar.','000':'Face remains coherent. White curved neck band persists, with darker rough diagonal marks along its edges. No convincing rectangular clerical tab.','030':'Face remains coherent. Pronounced dark pitted/scratch-like right-neck texture persists and looks darker/more extensive at50 than baseline. This is a local photographic-quality failure, despite no broad face collapse. Partial second person at left is preexisting.','028':'HOLDOUT: face, beard and smile remain coherent. Shirt edges darken slightly; no convincing central clerical white tab.','b2-055':'Face/glasses remain coherent. Broad ragged bright strip and glossy/smeared dark garment remain. Surround darkening does not turn this into clean fabric.','b2-051':'Face remains coherent. White central patch remains partly collar-like, with rough skin blending at the right edge; not a clean quality pass.','b2-020':'Face and harsh lighting remain coherent. Bright chin/neck patch persists, without a clearly separated clerical tab.','unseen-000':'Face remains coherent. Hat, partial extra person and ordinary neckline remain; ineligible.','unseen-001':'Face remains coherent. Ordinary shirt neckline remains, no clerical tab.','unseen-002':'Face remains coherent. Microphone/ambiguous hand-chin detail remains; no clerical collar.','unseen-003':'Face remains coherent. Cap and partial extra person remain; age not established; ineligible.'}
for step in [25,50]:
 d=p/'collar-surround'/f'preview-{step:03}';e=json.loads((d/'evaluation.json').read_text());rows=[]
 for r in e['rows']:
  f=d/r['outputs']['gray']['path'];h=hashlib.sha256(f.read_bytes()).hexdigest();assert h==r['outputs']['gray']['sha256']
  note=notes[r['id']]
  if step==25 and r['id']=='030':note='Face remains coherent. Pronounced dark pitted/scratch-like right-neck texture persists; local photographic-quality failure. Partial second person at left is preexisting.'
  rows.append({'id':r['id'],'split':r['split'],'native_image_sha256':h,'native_visual_review':note})
 out={'branch':'collar-surround','probe_step':step,'reviewed_unix':time.time(),'native_resolution':1024,'evaluation_sha256':hashlib.sha256((d/'evaluation.json').read_bytes()).hexdigest(),'all_11_native_gray_pngs_viewed':True,'gray_files_are_RGB_mode':True,'new_broad_face_collapse_observed':False,'production_approved':False,'limitations':'Small fixed sample; no proof of identity or distributional diversity. Notes compare both25/50 to the baseline; explicit at50 observations apply only to50. No eligibility sampler.','rows':rows}
 (p/f'visual-review-collar-surround-{step:03}.json').write_text(json.dumps(out,indent=2)+'\n')
